/* Founder completion. Extends the existing router, persistence and diagnostic engine. */
const assetFor=p=>ASSET[(p||'').split('/').pop()]||p;
const sceneFor=c=>ASSET[(c==='webcam'?'category-camera':c==='mic'?'category-microphone':c==='light'?'category-lighting':c==='accessories'?'category-accessories':'travel-detail')+'.webp'];
const evidenceWhy={facecam:'Watch the focus and exposure tests before choosing a fixed-focus webcam.',mv7:'Hear USB processing and comparison samples; choose a repeatable voice setting.',q2u:'Hear how close microphone technique changes the USB and XLR results.',sm7:'Listen to the SM7B segment; plan clean interface gain and the entire signal chain.',key:'See the original-generation panel in a real desk lighting setup.',plus:'Decide whether dials solve a real workflow problem before paying for them.',brio:'Compare framing, light and sharpness rather than assuming a 4K call.',canon:'Understand video and lens limitations before committing to a camera chain.',neo:'Compare shortcut convenience with a keyboard you already own.',cubes:'See construction and packing tradeoffs; this review covers the Blast family.',stream:'Decide whether repeatable controls justify a dedicated device.',dji:'Use the actual USB webcam walkthrough to rehearse a travel camera at your desk.',yeti:'Check room noise and microphone technique before upgrading an existing Yeti.'};
function reviewKey(r){return Object.keys(RESEARCH.reviews).find(k=>RESEARCH.reviews[k].url===r?.url)}
reviewBlock=function(i){if(!i.review)return '<p class="review-context">No product-specific independent review verified. Use the manufacturer source and rehearse the complete setup.</p>';const r=i.review,k=reviewKey(r);return `<div class="product-review"><a class="review-media" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer"><img src="${r.video?'https://i.ytimg.com/vi/'+r.video+'/hqdefault.jpg':assetFor(i.image)||sceneFor(i.cat)}" alt="${r.video?'Video thumbnail: '+esc(r.title):esc(i.name)+' · linked written review'}" loading="lazy" referrerpolicy="no-referrer"><span><small>${esc(r.by)} · INDEPENDENT</small><b>${esc(r.title)}</b><span class="watch">${r.video?'▶ Watch review':'Read review'} ↗</span></span></a><p class="review-context">${esc(evidenceWhy[k]||'Compare the exact model and the reviewer’s test conditions.')} No endorsement of MissionMed.</p></div>`;};
productVisual=function(i,c={}){if(!i.image&&i.review?.video)return `<figure class="product-visual"><a href="${esc(i.review.url)}" target="_blank" rel="noopener noreferrer"><img src="https://i.ytimg.com/vi/${i.review.video}/hqdefault.jpg" alt="Independent exact-model review thumbnail: ${esc(i.name)}" loading="lazy" referrerpolicy="no-referrer"></a><figcaption>${esc(i.review.by)} review thumbnail · original product photos at manufacturer</figcaption>${external(i.source||amazonUrl(i),'Original product photos','photo-link')}</figure>`;return `<figure class="product-visual"><img class="${i.image?'':'scene-reference'}" src="${i.image?assetFor(i.image):sceneFor(c.id)}" alt="${i.image?esc(i.name)+' · sourced product photograph':'Interview preparation scene; exact product imagery is linked below'}" loading="lazy">${!i.image?'<figcaption>Preparation scene · product photos at original source</figcaption>':''}${i.asin?external(i.source||amazonUrl(i),'Original product photos','photo-link'):''}</figure>`;};
tierCard=function(i,c,g){i.cat=c.id;const t=tierOf(i.t);return `<article class="tier" aria-label="${esc(t.name)}: ${esc(i.name)}" data-tier="${i.t}"><div class="tier-heading"><strong>${t.name}</strong>${ico(t.icon)}</div>${productVisual(i,c)}<div class="product-title"><span class="tier-label">${c.pick===i.t?'OUR CONSIDERED STARTING POINT':t.sub}</span><h3>${esc(i.name)}</h3></div><div><span class="tier-label">MISSIONMED INTERVIEW TAKE</span><p>${esc(i.why)}</p></div><div><span class="tier-label">BEST FOR · COMPLEXITY</span><p>${esc(i.best)}<br><b>${esc(i.complexity)}</b> · ${esc(i.ecosystem)}</p></div><div><span class="tier-label">WHAT YOU GAIN</span><ul>${i.pros.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><p>${esc(i.up||'Greater control is useful only when it solves a rehearsed need.')}</p></div><div class="setup-cell"><span class="tier-label">TRADEOFFS · COMPLETE SETUP</span><ul>${i.cons.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><p>${esc(i.setup)}</p></div><div class="setup-cell"><span class="tier-label">IN THE BOX · WHAT ELSE</span><p>${esc(i.box)}</p>${i.source?external(i.source,'Manufacturer / source details'):''}<p>${esc(i.down||'Keep equipment that already passes your setup check.')}</p></div><div><span class="tier-label">WATCH / READ THE EXPERTS</span>${reviewBlock(i)}</div><div class="buyer-boundary"><span class="tier-label">BUYER FEEDBACK · CURRENT PRICE</span>${i.asin?external(amazonUrl(i),'Check current Amazon rating, reviews and stock'):'No purchase required.'}${i.exception?'<p>Owner-approved Elgato rating exception. Check buyer feedback carefully.</p>':''}<small>Exact listing evidence is dated in the research ledger. No unverified deal or star claims.</small></div><div class="actions">${i.asin?external(amazonUrl(i),'Shop exact model','btn gold sm'):''}<button class="btn plain sm" data-kit="${esc(i.key)}" aria-pressed="${kit.has(i.key)}">${kit.has(i.key)?'Saved ✓':'Save to kit'}</button></div></article>`;};
function bindTierDeck(root){const deck=root.querySelector('.tier-deck');if(!deck)return;const cards=[...deck.children],out=root.querySelector('.tier-switch output'),prev=root.querySelector('[data-tier-prev]'),next=root.querySelector('[data-tier-next]');const index=()=>cards.reduce((best,c,i)=>Math.abs(c.offsetLeft-deck.offsetLeft-deck.scrollLeft)<Math.abs(cards[best].offsetLeft-deck.offsetLeft-deck.scrollLeft)?i:best,0);const update=()=>{const n=index();out.textContent=`${TIERS[n].name} · ${n+1} / 3`;prev.disabled=n===0;next.disabled=n===2;};const go=d=>{const n=Math.max(0,Math.min(2,index()+d));deck.scrollTo({left:cards[n].offsetLeft-cards[0].offsetLeft,behavior:paused||motionQuery.matches?'auto':'smooth'});};prev.onclick=()=>go(-1);next.onclick=()=>go(1);let raf=0;deck.addEventListener('scroll',()=>{if(!raf)raf=requestAnimationFrame(()=>{raf=0;update();});},{passive:true});deck.onkeydown=e=>{if(e.target!==deck)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();go(e.key==='ArrowRight'?1:-1);}};update();}
renderCatalog=function(g){const cats=CATALOG[g],cur=location.hash.split('/')[1],c=cats.find(x=>x.id===cur)||cats[0],nav=document.getElementById('catnav-'+g),host=document.getElementById('catalog-'+g);nav.setAttribute('role','group');nav.setAttribute('aria-label','Gear categories');nav.innerHTML=cats.map(x=>`<button data-cat="${x.id}" aria-pressed="${x.id===c.id}">${esc(x.name)}</button>`).join('');nav.querySelectorAll('button').forEach(b=>b.onclick=()=>location.hash=`#${g}/${b.dataset.cat}`);host.innerHTML=(g==='online'?ecosystem():'')+`<div class="tier-intro"><div><span class="eyebrow">THREE PATHS · ONE CLEAR COMPARISON</span><h2>${esc(c.name)}</h2><p class="lede">${esc(c.intro)}</p></div><a class="btn ghost sm" href="#test">Check what you own →</a></div><div class="tier-legend"><div><strong>Business Class</strong>Reliable value. Pay for what solves the problem.</div><div><strong>First Class</strong>More control and comfort. Rehearse the added features.</div><div><strong>Private Jet</strong>A complete studio or travel workflow. Count every component.</div></div><div class="tier-switch"><button data-tier-prev aria-label="Previous tier">←</button><output aria-live="polite">Business Class · 1 / 3</output><button data-tier-next aria-label="Next tier">→</button></div><div class="tier-deck" tabindex="0" role="region" aria-label="Compare Business Class, First Class and Private Jet">${c.items.map(i=>tierCard(i,c,g)).join('')}</div>`;if(g==='online'&&c.id==='webcam'){const i=RESEARCH.alternatives[0];i.cat='webcam';host.insertAdjacentHTML('beforeend',`<section class="paper reveal"><span class="eyebrow">ALREADY OWN A DJI CAMERA?</span><h3>Keep a camera that already works.</h3><p>${esc(i.why)}</p><p>${esc(i.setup)}</p>${reviewBlock(i)}${external(amazonUrl(i),'Original Pocket 3 listing','btn plain sm')}</section>`);}const held=RESEARCH.held.filter(x=>g==='online'?!/Samsonite|Travelpro/.test(x.name):/Samsonite|Travelpro|Anker/.test(x.name));host.insertAdjacentHTML('beforeend',`<details class="held-research"><summary>Why some familiar products are absent</summary><p>Exact listings that did not pass the dated qualification check are held. This does not mean you should replace equipment you already own.</p><ul>${held.map(x=>'<li>'+esc(x.name)+' — '+esc(x.reason)+'</li>').join('')}</ul></details>`);bindEditorial(host);bindTierDeck(host);};
const reviewCategories={canon:'Camera',facecam:'Camera',brio:'Camera',dji:'Camera',mv7:'Audio',q2u:'Audio',sm7:'Audio',yeti:'Audio',key:'Lighting',neo:'Accessories',plus:'Accessories',stream:'Accessories',cubes:'Travel'};
let expertFilter='All';function renderExperts(){const h=document.getElementById('experts');h.className='expert-index';document.getElementById('expertFilters')?.remove();h.insertAdjacentHTML('beforebegin',`<div id="expertFilters" class="expert-filters" role="group" aria-label="Filter expert reviews">${['All','Camera','Audio','Lighting','Accessories','Travel','Style'].map(x=>`<button data-expert-filter="${x}" aria-pressed="${expertFilter===x}">${x}</button>`).join('')}</div>`);const rs=Object.entries(RESEARCH.reviews).filter(([k])=>expertFilter==='All'||reviewCategories[k]===expertFilter);h.innerHTML=rs.map(([k,r])=>{const i=allItems().find(i=>i.review?.url===r.url)||RESEARCH.alternatives.find(i=>i.review?.url===r.url)||{};return `<article class="expert-feature reveal"><a class="expert-poster" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer"><img src="${r.video?'https://i.ytimg.com/vi/'+r.video+'/hqdefault.jpg':assetFor(i.image)||sceneFor(i.cat)}" alt="${r.video?'Review video thumbnail: ':'Product image for written review: '}${esc(r.title)}" loading="lazy" referrerpolicy="no-referrer"><span class="play">${r.video?'▶ WATCH':'READ'} ↗</span></a><div class="copy"><span class="eyebrow">${reviewCategories[k]} · ${esc(r.by)}</span><h3>${esc(r.title)}</h3><p>${esc(evidenceWhy[k])}</p>${external(r.url,r.video?'Watch the original':'Read the original')}<p class="note">Independent evidence. No MissionMed endorsement.</p></div></article>`;}).join('');if(expertFilter==='Style')h.innerHTML=`<article class="paper" style="grid-column:1/-1"><h3>Fit before a product review.</h3><p>Our style guidance is an editorial planning aid. We have not verified independent tests of every garment. Read the actual fabric, size and return information beside each outfit piece, then rehearse it seated and standing.</p>${external('https://students-residents.aamc.org/applying-residency/virtual-interviews-applicant-preparation-guide','AAMC virtual interview preparation')}<a class="btn plain" href="#dress">Open Style Studio →</a></article>`;document.querySelectorAll('[data-expert-filter]').forEach(b=>b.onclick=()=>{expertFilter=b.dataset.expertFilter;renderExperts();});bindEditorial(h);}
renderPrimeDay=function(){const picks=CATALOG.online.filter(c=>['webcam','mic','light','accessories'].includes(c.id)).map(c=>[c,c.items.find(i=>i.t===c.pick&&i.asin)||c.items.find(i=>i.asin)]);document.getElementById('primeday').innerHTML=`<div class="editorial-note">Deals worth watching. No current offer or sale event has been verified. Check the exact model, return terms and complete setup before deciding.</div><div class="shopping-story">${picks.map(([c,i],n)=>`<article class="deal-feature reveal"><div class="deal-photo"><img src="${assetFor(i.image)||sceneFor(c.id)}" alt="${i.image?esc(i.name):'Preparation scene · original product photos linked'}" loading="lazy"></div><div class="deal-copy"><span class="eyebrow">0${n+1} · ${c.name} · ${tierOf(i.t).name}</span><h3>${esc(i.name)}</h3><p>${esc(i.why)}</p><p><b>Before you buy:</b> ${esc(i.setup)}</p>${reviewBlock(i)}<div class="actions">${external(amazonUrl(i),'Check current listing','btn gold sm')}<button class="btn plain sm" data-kit="${esc(i.key)}" aria-pressed="${kit.has(i.key)}">${kit.has(i.key)?'Saved ✓':'Save to kit'}</button></div></div></article>`).join('')}</div>`;bindEditorial(document.getElementById('primeday'));};
document.querySelectorAll('[data-nav="prime-day"] span').forEach(e=>e.textContent='Deals Worth Watching');document.querySelector('#drawer [data-nav="prime-day"]').textContent='Deals Worth Watching';document.getElementById('page-prime-day').dataset.title='Deals Worth Watching';

/* Explicit personal preferences. No image-derived traits or sizing claims. */
const styleDefaults={presentation:'women',context:'in-person',climate:'temperate',budget:'500',contrast:'balanced',palette:'navy',proportions:'no-preference',fit:'regular',formality:'formal',preferences:'',owned:''};
let styleProfile={...styleDefaults,...store.get('styleProfile',{})};let outfitDraft=store.get('outfitDraft',{name:'My interview outfit',pieces:{}});let editOutfitId=null,compareIds=[];let bodyPhotoURL='',studioFaceURL='';
const styleSlots=[['jacket','Suit jacket / blazer'],['bottom','Trousers / skirt'],['dress','Dress (optional)'],['top','Shirt / blouse'],['shoes','Shoes'],['tie','Tie / finishing detail'],['belt','Belt'],['bag','Bag / portfolio'],['outerwear','Weather layer']];
const fashionById=id=>FASHION.products.find(p=>p.id===id);const forPresentation=p=>styleProfile.presentation==='any'||p.presentation==='any'||p.presentation===styleProfile.presentation;
function outfitProducts(l=outfitDraft){return Object.values(l.pieces||{}).map(fashionById).filter(Boolean)}
function outfitCost(l=outfitDraft){const ps=outfitProducts(l),sum=ps.reduce((v,p)=>v+(p.price||0),0);return {sum,complete:ps.every(p=>p.price),count:ps.length};}
function collage(l=outfitDraft){const ps=outfitProducts(l);return `<div class="outfit-collage">${ps.length?ps.map((p,n)=>`<div class="outfit-piece ${['jacket','dress'].includes(p.slot)?'major':''}" style="--entrance:${n}"><img src="${assetFor(p.image)}" alt="${esc(p.name)}" loading="lazy"><span>${esc(p.brand)} · ${esc(p.color||p.slot)}</span></div>`).join(''):figureSVG(look)}${Object.entries(l.pieces||{}).filter(([,id])=>id==='owned').map(([slot])=>`<div class="outfit-piece"><div class="owned-mark">Yours.</div><span>${esc(styleSlots.find(x=>x[0]===slot)?.[1]||slot)} · use what you own</span></div>`).join('')}</div>`;}
function seedOutfit(presentation=styleProfile.presentation,type='trousers'){const p= presentation==='men'?'men':'women';const preset=FASHION.outfits.find(x=>x.presentation===p&&x.kind===type)||FASHION.outfits.find(x=>x.presentation===p);outfitDraft={name:preset?.name||'My interview outfit',pieces:{...preset?.pieces},kind:type};store.set('outfitDraft',outfitDraft);}
if(!Object.keys(outfitDraft.pieces||{}).length)seedOutfit();
const education={
men:[['The suit: navy or charcoal','Start with a matched jacket and trousers in navy or charcoal for a formal interview. Check the program’s instructions. Fit matters more than a label: shoulders sit cleanly, the button closes without an X-shaped pull, and the lapels lie flat. Separate dark garments can photograph as a mismatch; compare them in daylight.'],['Tailoring and proportions','Choose regular, slim or relaxed cuts by comfort, not an aspirational size. If you want a longer vertical line, try coherent jacket and trouser colors; if you prefer more room, try a straighter leg. These are optional visual effects, not body corrections. Leave time for sleeve, waist and hem alterations.'],['The shirt and collar','A white or soft blue shirt gives predictable contrast. Test the collar buttoned with your intended tie; it should feel comfortable while speaking and turning your head. Check gaping, sleeve length and transparency under interview light. Fine stripes can shimmer after video compression.'],['Tie and finishing details','For a formal interview, a quiet navy or burgundy tie is a conventional option. Match tie width to the lapels; the tip generally reaches the belt area. Rehearse the knot and avoid oversized novelty patterns. A pocket square is optional; a careful fit needs no decoration.'],['Shoes and socks','Polished, familiar dress shoes are a dependable choice. Break them in before travel; do not debut painful shoes on a hospital tour. Choose socks long enough to cover the leg when seated. Check soles, laces and whether the shoes squeak on hard floors.'],['Belt, watch and bag','Coordinate the belt with the shoe color when practical. Keep a watch and accessories unobtrusive; remove a noisy bracelet during microphone testing. A slim portfolio or structured bag should hold documents without forcing you to juggle multiple items. Existing clean accessories are enough.'],['Grooming and personal presentation','Arrange any haircut early enough to feel like yourself. Keep facial hair, nails and clothing tidy in the way you prefer. Fragrance is optional; a hospital day can involve people sensitive to scents. Cultural and religious presentation choices remain yours.'],['On camera','Wear the complete outfit for your rehearsal, even when the camera crops at the chest. Sit at the intended desk and check shirt contrast, collar shape, tie texture and reflections in glasses. Use the live setup test to assess visibility rather than buying for a hypothetical camera problem.'],['The in-person interview day','Walk stairs, sit, reach for your portfolio and put on your weather layer. Keep a compact backup shirt and stain tool if useful. Choose a coat that accommodates the jacket rather than compressing the shoulders. Follow the program’s guidance for tours or clinical areas.'],['The pre-interview dinner','Use the invitation’s dress instructions. If explicitly casual, neat trousers, a collared shirt and a blazer can be appropriate; an open collar is an option. Do not assume the dinner and interview require the same formality. Comfortable interaction matters more than a conspicuous brand.'],['Travel without the scramble','Pack the suit to minimize pressure on the lapels, protect shoe uppers and keep documents accessible. Follow the fabric care label; not every garment should be steamed. Inspect the outfit after arrival and allow enough drying or pressing time.'],['Final fitting and avoidable mistakes','Try the entire look while seated for twenty minutes. Check sleeve and trouser lengths with the actual shoes. Remove temporary stitching only when intended by the garment maker. Avoid a too-tight collar, mismatched dark separates, last-minute tailoring and purchases without workable return terms.']],
women:[['The tailored trouser suit','A matched navy, charcoal or black jacket and trousers provides a clear formal starting point. Compare the exact fabric and color family before calling separates a suit. Choose enough ease to sit, walk and gesture. A wide or straight leg is a personal preference, not a professionalism score.'],['The skirt suit','Choose the hem by your comfort, the program’s expectations and how it behaves while seated. Try stairs and a long chair rehearsal. Check the slit, lining, waistband and jacket movement. Hosiery is a personal or context-dependent choice; have a spare if you decide to wear it.'],['The dress and blazer','A simple dress plus a structured jacket can make a coherent interview outfit. Check seated coverage, opacity, neckline and jacket length together. A short shirt dress may be better for a dinner than a formal interview; the product page’s name alone cannot establish appropriate coverage.'],['Blouses and necklines','Choose a top that stays comfortable and covered when you lean toward the camera or reach for a bag. Test light fabrics for transparency. A higher, quiet neckline and matte fabric often simplify video contrast. A camisole is optional; do not let a last-minute layer change the fit.'],['Fit, tailoring and proportions','Tell the stylist the effect you prefer. A coherent dark column can create a longer visual line; higher contrast can emphasize the top half in a camera crop. These are choices, not rules about your body. Check shoulders, bust ease, waist movement, sleeve length and the hem with your actual shoes.'],['Shoes: flats or heels','Both familiar polished flats and stable heels can work. Choose a heel height you can walk in through a tour, stairs and waiting periods. Test rubbing, grip and sound on hard floors. Pack a comfortable travel shoe; no one benefits from painful new shoes.'],['Hosiery and finishing layers','Use hosiery if it supports your comfort or the dress context. Check opacity and color in daylight; keep a spare if useful. Confirm that skirt or dress lining moves easily. A weather layer should accommodate the blazer without pulling.'],['Jewelry and accessories','Choose the jewelry you enjoy while keeping microphone noise and camera glare manageable. Test earrings, necklaces, a watch and glasses under interview light. Small accessories are a conventional option, not a requirement. Cultural and religious garments are part of your own presentation.'],['A bag that works all day','A structured tote or portfolio can keep documents, charger and essentials organized. Check weight, closure and handle comfort before a hospital tour. Carry only what you need; a bag you already own may be the best choice. Avoid claiming it fits a laptop without checking dimensions.'],['Hair and optional makeup','Wear a style that stays comfortable and keeps your face visible in the way you prefer. Makeup is optional; if used, test it under your interview lighting rather than making assumptions from a photo. Check glare, color cast and how the look feels over a full day.'],['For an online interview','Rehearse the complete outfit in your actual chair. Check blouse contrast, jacket lapels, neckline when leaning and jewelry noise. Fine patterns, shiny fabrics and strong backlight can distract after video compression. Use Test My Setup for the practical answer.'],['For an in-person day','Rehearse sitting, standing, walking and reaching with the bag and weather layer. Keep comfortable shoes, a backup top and your own small repair essentials if useful. Plan for indoor air conditioning and outdoor weather without treating fashion as a substitute for comfort.'],['The pre-interview dinner','Read the invitation. A dress, tailored separates or a blazer with a simple top can suit a dinner when the stated formality allows it. Use a familiar outfit that lets you concentrate on conversation. Do not presume a shorter product styled for nightlife is a residency interview recommendation.'],['Travel and garment care','Follow the garment’s fabric and care instructions. Fold or hang to protect structure; do not apply high heat or steam blindly. Inspect the outfit after arrival, protect shoes and keep backup layers accessible. Leave time to press or arrange professional care.'],['The final tailor visit','Bring the shoes and underlayers you will wear. Check sleeve length, trouser hem, skirt/dress coverage, waist ease and movement while seated. Allow time for a second fitting. Do not choose an online size from a photo or let the style planner imply measured fit.'],['Mistakes you can prevent','Avoid last-minute untested shoes, gaping blouse buttons, mismatched suit fabric, see-through light tops, noisy accessories and a hem that changes unexpectedly when seated. Check return terms and shipping before ordering. Buy a missing piece only when it improves a real plan.']]
};
function suggestedOutfit(){
 const p=styleProfile,men=p.presentation==='men',preset=FASHION.outfits.find(x=>x.presentation===(men?'men':'women')&&x.kind==='trousers');
 const pieces={...preset.pieces},reasons=[];
 if(p.palette==='navy'&&men){pieces.jacket=p.fit==='slim'?'jc-jacket':'br-jacket';pieces.bottom=p.fit==='slim'?'jc-trouser':'br-trouser';reasons.push(`Your navy palette and ${p.fit} fit preference point to ${p.fit==='slim'?'the J.Crew Ludlow slim pair':'the Banana Republic tailored pair'}. Check shoulder ease and seated movement; a cut label does not prove fit.`);}
 else if(p.palette==='black'&&!men){pieces.jacket='ann-jacket';pieces.bottom='ann-pant';reasons.push('Your black palette points to the Ann Taylor Seasonless Stretch jacket and trouser pair. Verify the exact fabric and color together, then check sleeve length and the hem with your chosen shoes.');}
 else if(!men&&p.palette==='navy'&&p.formality==='relaxed'&&p.context==='dinner'){pieces.jacket='q-blazer';pieces.bottom='q-skirt';reasons.push('For your navy preference and relaxed dinner, consider the Quince navy blazer with black skirt as deliberate separates. They are not a matched suit; use them only when the invitation permits.');}
 else{pieces.jacket='owned';pieces.bottom='owned';reasons.push(`The sourced shortlist does not establish a matched ${p.palette==='other'?'custom-palette':p.palette} suit for your selected presentation. Keep an owned matched pair or verify another retailer rather than substituting a color you did not choose.`);}
 if(p.fit==='relaxed'||p.proportions==='relaxed'){pieces.jacket='owned';pieces.bottom='owned';reasons.push('You selected relaxed fit or silhouette. The researched matched suits are not verified relaxed cuts, so start with a comfortable owned pair; check shoulder movement and waist ease while seated.');}
 if(p.proportions==='lengthen')reasons.push('For your preferred longer visual line, compare jacket and bottom together in daylight. Keep their colors coherent and tailor the hem with the actual shoes; this is an optional visual effect.');
 if(men&&p.contrast==='soft'){pieces.top='owned';reasons.push('Your soft-contrast preference favors an owned solid pale-blue or quiet off-white shirt with navy. The sourced J.Crew shirt is white, so we are not substituting it without your choice.');}else reasons.push(`The ${men?'white J.Crew Oxford':'ivory Quince silk blouse'} offers ${p.contrast==='strong'?'clearer':'quiet'} contrast. ${p.context==='online'?'In your online frame, test the solid fabric for exposure and glare; avoid micro-check patterns that may shimmer.':'Check opacity, collar or neckline and button spacing while seated.'}`);
 if(p.climate==='cold'){pieces.outerwear=men?'owned':'q-coat';reasons.push('For your cold-weather choice, add a coat with room over the jacket. The Quince crepe trench is a layer to compare, not a verified winter-insulation recommendation.');}
 if(p.climate==='wet'){pieces.outerwear='owned';reasons.push('For likely rain, use your own weather-protective coat and umbrella. The sourced crepe trench does not establish waterproof performance.');}
 if(p.context==='dinner'&&p.formality==='relaxed'){pieces.tie='';reasons.push('For the relaxed dinner formality you selected, an open collar is an option when the invitation allows it. Keep a tie for the formal interview if that suits your presentation.');}
 Object.entries(outfitDraft.pieces||{}).filter(([,v])=>v==='owned').forEach(([k])=>pieces[k]='owned');
 let sum=outfitCost({pieces}).sum;const budget=Math.max(0,Number(p.budget)||0),removed=[];
 Object.entries(pieces).map(([slot,id])=>({slot,p: fashionById(id)})).filter(x=>x.p?.price).sort((a,b)=>b.p.price-a.p.price).forEach(x=>{if(sum>budget){pieces[x.slot]='owned';sum-=x.p.price;removed.push(x.p.name);}});
 reasons.push(removed.length?`To keep the known-price subtotal within your $${budget} budget, retain owned alternatives for: ${removed.join('; ')}. Unpriced suit pieces, tax, delivery and tailoring still need checking.`:`Known-price subtotal is $${sum.toFixed(2)} against your $${budget} budget. Unpriced suit pieces, tax, delivery and tailoring prevent a full-cost guarantee.`);
 if(p.preferences||p.owned)reasons.push('Your written preferences and owned-piece notes remain yours to interpret. The builder preserves slots already marked “Use my own”; confirm coverage, cultural preferences and comfort explicitly before shopping.');
 return {name:'My considered '+(p.context==='dinner'?'dinner':'interview')+' plan',kind:'trousers',pieces,reasons};
}
function stylistAdvice(){const p=styleProfile;const points=[['Your color story',p.contrast==='soft'?'You chose soft contrast. Try ivory or pale blue with navy or charcoal; use Test My Setup to confirm that the blouse or shirt remains distinct under your light.':p.contrast==='strong'?'You chose strong contrast. A white or ivory top with a dark jacket gives a clear camera crop; test glare and exposure rather than guessing from your complexion.':'You chose balanced contrast. Start with a dark tailored layer and a quiet light top; adjust it to the colors you actually enjoy.'],['Your fit preference',p.proportions==='lengthen'?'You asked for a longer visual line. Consider coherent dark top and bottom colors and a clean trouser break; treat this as a preference, never a requirement to change your body.':p.proportions==='relaxed'?'You prefer visual and physical ease. Try a straighter trouser or a jacket with enough movement; a seated fitting will tell you more than a size label.':'You did not request a proportion effect. Prioritize shoulders, comfortable waist ease and a hem that works with your chosen shoes.'],['Your interview context',p.context==='online'?'For your online interview, check the chest-up frame, neckline, fabric shimmer and accessory noise. Rehearse the full outfit and keep a backup top nearby.':p.context==='dinner'?'For your dinner, use the invitation’s stated formality. '+(p.formality==='formal'?'Your formal preference supports a tailored suit or dress and blazer.':'Your chosen relaxed formality supports neat separates if the invitation allows them.'):'For your in-person day, rehearse a hospital tour, stairs and a long seated conversation. '+(p.climate==='cold'?'Choose a coat that fits over the blazer.':p.climate==='warm'?'Consider breathable layers and indoor air conditioning.':'Keep a comfortable weather layer available.')],['Your suit palette and cut',`You selected ${p.palette==='other'?'your own palette':p.palette} and ${p.fit} fit. ${p.fit==='slim'?'Compare the slim Ludlow pair only if shoulders, seat and waist remain comfortable.':p.fit==='relaxed'?'The current matched-suit shortlist does not verify a relaxed cut; keep an owned pair or choose a verified relaxed option.':'A tailored label still needs a seated fitting and appropriate shoulder ease.'}`],['Your budget',`Your stated budget is $${Number(p.budget)||0}. Keep owned pieces first. The outfit shows dated retailer prices where verified; shipping, tax, tailoring and missing prices are excluded.`],['Your own preferences',p.preferences?`You told us: ${p.preferences}. Use those preferences to review the suggestions; we do not infer color, gender, religion, ethnicity or body measurements from photos.`:'Add colors, coverage, cultural or religious preferences and comfort needs only if you want them considered. Photos never supply these profile fields.'],['Your existing wardrobe',p.owned?`You already own: ${p.owned}. Choose “Use my own” for those slots and buy only the gaps.`:'List the pieces you already own, or mark them in the builder. A complete plan can involve no shopping.']];return `<section class="stylist-response"><span class="eyebrow">YOUR PERSONAL RESIDENCY INTERVIEW STYLIST</span><h2>A considered plan, with reasons.</h2><div class="advice-points">${points.map(([h,t])=>`<div><h3>${h}</h3><p>${esc(t)}</p></div>`).join('')}</div><div class="stylist-candidate"><h3>Your next outfit, piece by piece.</h3><p>These explainable suggestions use your choices and the verified shortlist. Apply them when you are ready; your saved looks stay in My Wardrobe.</p><ul>${suggestedOutfit().reasons.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><button class="btn gold" id="applyStylePlan">Build this considered outfit →</button></div></section>`;}
const profileFields=[['context','Interview setting',[['in-person','In-person interview'],['online','Online interview'],['dinner','Pre-interview dinner']]],['climate','Weather / climate',[['temperate','Mild or mixed'],['warm','Warm'],['cold','Cold'],['wet','Rain likely']]],['contrast','Preferred color contrast',[['balanced','Balanced'],['soft','Soft'],['strong','Strong']]],['palette','Favorite suit palette',[['navy','Navy'],['charcoal','Charcoal'],['black','Black'],['other','My own palette']]],['proportions','Preferred visual effect',[['no-preference','No preference'],['lengthen','Longer visual line'],['relaxed','Relaxed silhouette']]],['fit','Preferred fit',[['regular','Regular'],['slim','Slim'],['relaxed','Relaxed']]],['formality','Chosen formality',[['formal','Formal'],['relaxed','Relaxed, if event allows']]]];
function profileHTML(){return `<section class="style-profile"><div><span class="eyebrow">START WITH YOUR CHOICES</span><h2>Your style.<br>Your comfort.<br>Your next chapter.</h2><p>Tell us what you prefer. The stylist explains its suggestions using these choices. It never reads personal traits or measurements from a photo.</p><p>Profile and wardrobe stay on this browser. Clear them whenever you choose.</p><button class="btn plain sm" id="clearStyleProfile">Reset profile</button></div><div class="profile-fields">${profileFields.map(([k,n,opts])=>`<label>${n}<select data-profile="${k}">${opts.map(([v,l])=>`<option value="${v}" ${styleProfile[k]===v?'selected':''}>${l}</option>`).join('')}</select></label>`).join('')}<label>Outfit budget (USD)<input type="number" min="0" max="20000" step="25" value="${esc(styleProfile.budget)}" data-profile="budget"></label><label class="wide">Colors, coverage and comfort preferences (optional)<input maxlength="250" data-profile="preferences" value="${esc(styleProfile.preferences)}" placeholder="For example: matte fabrics, covered neckline, no heels"></label><label class="wide">Pieces you already own (optional)<input maxlength="250" data-profile="owned" value="${esc(styleProfile.owned)}" placeholder="For example: navy suit, black loafers, brown portfolio"></label><span class="profile-status" role="status">Saved on this device. No photo-based inference.</span></div></section>`;}
function boardHTML(l=outfitDraft){const cost=outfitCost(l);return `<div class="outfit-board"><span class="eyebrow">YOUR COMPLETE LOOK · LOCAL OUTFIT BOARD</span><h3>${esc(l.name||'My interview outfit')}</h3>${collage(l)}<p class="cost">${cost.count?'$'+cost.sum.toFixed(2)+(cost.complete?'':' + unpriced pieces'):'Use your own wardrobe'}</p><p class="board-caption">Observed retailer prices on ${FASHION.observedOn}; may change. Tax, shipping and alterations excluded. This is a collage of actual product photography, not a prediction of fit or a photorealistic try-on.</p>${cost.sum>Number(styleProfile.budget)?'<p class="board-caption"><b>Above your stated budget.</b> Keep owned pieces or change the selected items.</p>':''}<div class="shop-look">${outfitProducts(l).map(p=>external(p.url,esc(p.slot))).join('')}</div></div>`;}
function builderHTML(){return `<div class="outfit-slots"><span class="eyebrow">CHOOSE THE PIECES · BUY ONLY THE GAPS</span><h2>Build your complete outfit.</h2>${styleSlots.map(([slot,label])=>{const selected=fashionById(outfitDraft.pieces[slot]);const options=FASHION.products.filter(p=>p.slot===slot&&forPresentation(p));return `<div class="slot-row">${selected?`<img src="${assetFor(selected.image)}" alt="${esc(selected.name)}" loading="lazy">`:'<div class="owned-mark" aria-hidden="true">—</div>'}<div><label>${label}<select data-outfit-slot="${slot}"><option value="">Leave out / decide later</option><option value="owned" ${outfitDraft.pieces[slot]==='owned'?'selected':''}>Use my own ${label.toLowerCase()}</option>${options.map(p=>`<option value="${p.id}" ${selected?.id===p.id?'selected':''}>${esc(p.brand+' · '+p.name)}${p.price?' · $'+p.price:''}</option>`).join('')}</select></label>${selected?`<p>${esc(selected.take)}</p><p><b>Fit / care:</b> ${esc(selected.fit)}</p><p><b>Availability:</b> ${esc(selected.availability||'Size and color stock vary; check the retailer.')}</p>${external(selected.url,'Shop the exact piece')} · ${external(selected.url,'Fabric, size & return details')}`:'<p>Keeping a familiar piece is a considered choice.</p>'}</div></div>`;}).join('')}<div class="look-save"><label for="completeLookName">Name this outfit</label><input id="completeLookName" maxlength="80" value="${esc(outfitDraft.name)}"><div class="actions"><button class="btn gold" id="saveCompleteLook">${editOutfitId?'Update':'Save to My Wardrobe'} →</button><a class="btn plain" href="#wardrobe">Compare saved looks</a></div></div></div>`;}
function privateStudio(){return `<section class="studio-private reveal"><div><span class="eyebrow">PRIVATE PHOTO REFERENCES</span><h2>Your photo stays yours.</h2><p>A face photo can be a personal reference. A full-body photo is more useful for a future garment visualization. Neither is used to infer traits, measurements or fit, and neither is stored in the wardrobe.</p><div class="photo-reference"><figure>${studioFaceURL?`<img src="${studioFaceURL}" alt="Your local face reference">`:'<p>Face reference</p>'}<label for="studioFace">Choose face photo</label><input id="studioFace" type="file" accept="image/jpeg,image/png,image/webp"><button class="btn plain sm" data-clear-reference="face">Remove</button></figure><figure>${bodyPhotoURL?`<img src="${bodyPhotoURL}" alt="Your local full-body reference">`:'<p>Full-body reference</p>'}<label for="studioBody">Choose full-body photo</label><input id="studioBody" type="file" accept="image/jpeg,image/png,image/webp"><button class="btn plain sm" data-clear-reference="body">Remove</button></figure></div><p>Use an image under 10 MB. For a future try-on, use one person, even light, a simple background and unobstructed clothing. This local panel uploads nothing.</p></div><div><span class="eyebrow">EXISTING VIRTUAL TRY-ON · FASHN</span><h2>A researched path to garment visualization.</h2><p>Photorealistic virtual try-on is not available until the approved server gateway is provisioned. The local outfit board above is available now.</p><div class="tryon-blocker"><b>Exact external blocker:</b> the approved MissionMed server-side FASHN gateway has not been provisioned.</div><label class="tryon-consent"><input id="tryonConsent" type="checkbox"><span>I understand that an activated try-on would send my chosen full-body photo and garment reference to FASHN, externally. I would review a cost and retention notice before each request.</span></label><button class="btn plain" disabled>Try-on awaiting approved gateway</button><details class="tryon-contract"><summary>Provider, cost, privacy and integration boundary</summary><p>The existing tryon-v1.6 model uses one credit per output. The adapter selects one output, base64 input and base64 output; no frontend credential or public photo URL. Default CDN output retention is three days, base64 output is available for 60 minutes, and request records are not automatically deleted. Temporary base64 input copies are deleted after processing with a one-day backstop. Provider policy states no training use without separate express opt-in.</p><p>The included adapter validates consent, requires a server-side credential, excludes image content from logs, limits image size, polls bounded status and returns only a validated image response. It has been tested with synthetic transport, not with a paid request or personal photo.</p>${external('https://docs.fashn.ai/api-reference/tryon-v1-6','FASHN model and cost')} · ${external('https://docs.fashn.ai/api-overview/data-retention-privacy','Provider retention policy')}</details></div></section>`;}
renderLook=function(){const intro=dress.querySelector('.route-intro');[...dress.children].filter(x=>x!==intro).forEach(x=>x.remove());dress.insertAdjacentHTML('beforeend',`<div class="style-focus" role="group" aria-label="Style Studio presentation">${[['women','Women’s studio'],['men','Men’s studio'],['any','Any presentation']].map(([v,n])=>`<button data-studio-focus="${v}" aria-pressed="${styleProfile.presentation===v}">${n}</button>`).join('')}</div>${profileHTML()}<div id="personalAdvice">${stylistAdvice()}</div><div class="outfit-style-options" role="group" aria-label="Outfit starting points">${[['trousers','Tailored trousers'],['skirt','Skirt and blazer'],['dress','Dress and blazer']].filter(([v])=>styleProfile.presentation!=='men'||v==='trousers').map(([v,n])=>`<button class="btn ghost sm" data-complete-preset="${v}">${n} →</button>`).join('')}</div><div class="outfit-workbench"><div id="completeOutfitBoard">${boardHTML()}</div>${builderHTML()}</div><section class="style-curriculum"><div class="curriculum-heading"><span class="eyebrow">THE RESIDENCY INTERVIEW STYLE GUIDE</span><h2>The details.<br>The comfort.<br>The confidence.</h2><p>Read the guidance for the presentation you choose. These are practical options, not judgments about your body or identity.</p><img src="${ASSET['travel-detail.webp']}" alt="Supplied interview outfit and packing details" loading="lazy"></div><div class="style-lessons">${(styleProfile.presentation==='any'?[...education.women,...education.men]:education[styleProfile.presentation]).map(([t,d],n)=>`<details class="reveal" ${n===0?'open':''}><summary>${String(n+1).padStart(2,'0')} · ${t}</summary><p>${d}</p></details>`).join('')}</div></section><section class="paper reveal"><span class="eyebrow">REHEARSE THE COMPLETE OUTFIT</span><h2>A fitting you can trust.</h2><div id="fitChecks"></div><span class="pill" id="fitCount"></span><p>These checks are yours. No image model confirms garment size, coverage or comfort.</p></section>${privateStudio()}`);bindStudio();renderFitting();bindEditorial(dress);};
function bindStylePlan(){const b=document.getElementById('applyStylePlan');if(b)b.onclick=()=>{const {reasons,...plan}=suggestedOutfit();outfitDraft=plan;editOutfitId=null;store.set('outfitDraft',outfitDraft);renderLook();announce('Your explained style plan is ready to review in the outfit builder.');};}
function bindStudio(){bindStylePlan();dress.querySelectorAll('[data-studio-focus]').forEach(b=>b.onclick=()=>{styleProfile.presentation=b.dataset.studioFocus;store.set('styleProfile',styleProfile);seedOutfit();editOutfitId=null;renderLook();announce('Style presentation changed. Outfit starting point loaded.');});dress.querySelectorAll('[data-profile]').forEach(el=>el.onchange=()=>{styleProfile[el.dataset.profile]=el.value;store.set('styleProfile',styleProfile);document.getElementById('personalAdvice').innerHTML=stylistAdvice();document.getElementById('completeOutfitBoard').innerHTML=boardHTML();bindEditorial(document.getElementById('personalAdvice'));bindStylePlan();announce('Style profile saved on this device.');});dress.querySelectorAll('input[data-profile]').forEach(el=>el.oninput=el.onchange);document.getElementById('clearStyleProfile').onclick=()=>{styleProfile={...styleDefaults};store.set('styleProfile',styleProfile);renderLook();announce('Style profile reset.');};dress.querySelectorAll('[data-complete-preset]').forEach(b=>b.onclick=()=>{seedOutfit(styleProfile.presentation,b.dataset.completePreset);editOutfitId=null;renderLook();announce('Complete outfit starting point applied.');});dress.querySelectorAll('[data-outfit-slot]').forEach(el=>el.onchange=()=>{outfitDraft.pieces[el.dataset.outfitSlot]=el.value;if(el.dataset.outfitSlot==='dress'&&el.value){outfitDraft.pieces.bottom='';outfitDraft.pieces.top='';}if(['bottom','top'].includes(el.dataset.outfitSlot)&&el.value)outfitDraft.pieces.dress='';store.set('outfitDraft',outfitDraft);renderLook();dress.querySelector(`[data-outfit-slot="${el.dataset.outfitSlot}"]`)?.focus({preventScroll:true});announce('Outfit piece updated.');});document.getElementById('completeLookName').oninput=e=>{outfitDraft.name=e.target.value;store.set('outfitDraft',outfitDraft);dress.querySelector('.outfit-board h3').textContent=e.target.value||'My interview outfit';};document.getElementById('saveCompleteLook').onclick=()=>{const w=store.get('wardrobe',[]),id=editOutfitId||Date.now(),entry={...look,...outfitDraft,pieces:{...outfitDraft.pieces},profile:{...styleProfile},id,name:outfitDraft.name||'My interview outfit',presentation:styleProfile.presentation,format:'complete-outfit-v1'};const ix=w.findIndex(x=>x.id===id);ix>=0?w[ix]=entry:w.push(entry);store.set('wardrobe',w);editOutfitId=null;announce('Complete outfit saved privately on this device.');location.hash='#wardrobe';};[['studioFace','face'],['studioBody','body']].forEach(([id,type])=>document.getElementById(id).onchange=e=>{const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024){announce('Choose a JPEG, PNG or WebP under 10 MB.');e.target.value='';return;}const old=type==='face'?studioFaceURL:bodyPhotoURL;if(old)URL.revokeObjectURL(old);const u=URL.createObjectURL(f);type==='face'?studioFaceURL=u:bodyPhotoURL=u;renderLook();announce('Photo added as a local reference. Nothing uploaded.');});dress.querySelectorAll('[data-clear-reference]').forEach(b=>b.onclick=()=>{const type=b.dataset.clearReference,u=type==='face'?studioFaceURL:bodyPhotoURL;if(u)URL.revokeObjectURL(u);type==='face'?studioFaceURL='':bodyPhotoURL='';renderLook();announce('Local photo reference removed.');});}
renderWardrobe=function(){const w=store.get('wardrobe',[]),sel=store.get('selectedLook',null),h=document.getElementById('wardrobe');h.className='visual-wardrobe';compareIds=compareIds.filter(id=>w.some(l=>l.id===id));h.innerHTML=!w.length?`<div class="empty-state reveal" style="grid-column:1/-1"><span class="eyebrow">YOUR FIRST COMPLETE LOOK</span><h3>A calmer interview morning starts here.</h3><p>Build an outfit using your own pieces and the sourced shopping shortlist. Save it privately, compare a second look and choose what you will wear.</p><a class="btn gold" href="#dress">Enter Style Studio →</a></div>`:`<div class="compare-bar"><p>${w.length} saved ${w.length===1?'look':'looks'} · private on this device</p><span role="status">${compareIds.length} / 2 selected to compare</span></div>${w.map(l=>`<article class="wardrobe-look reveal">${l.pieces?collage(l):`<div class="look-art">${figureSVG(l)}</div>`}<div class="look-info"><span class="pill">${sel===l.id?'CHOSEN FOR YOUR INTERVIEW':'PRIVATE SAVED LOOK'}</span><h3>${esc(l.name)}</h3><p>${l.pieces?esc((l.presentation||'any')+' · '+(l.profile?.context||'interview')):'Earlier color and silhouette plan; preserved from your wardrobe.'}</p><div class="actions"><button class="btn gold sm" data-wear="${l.id}" aria-pressed="${sel===l.id}">${sel===l.id?'Selected ✓':'Wear this'}</button><button class="btn plain sm" data-complete-edit="${l.id}">Edit</button><button class="btn plain sm" data-compare-look="${l.id}" aria-pressed="${compareIds.includes(l.id)}">${compareIds.includes(l.id)?'Comparing ✓':'Compare'}</button><button class="btn plain sm" data-complete-delete="${l.id}">Delete</button></div></div></article>`).join('')}${compareIds.length===2?`<section class="outfit-compare">${compareIds.map(id=>{const l=w.find(x=>x.id===id),cost=outfitCost(l);return `<div><h3>${esc(l.name)}</h3>${l.pieces?collage(l):figureSVG(l)}<p>${l.pieces?'Observed priced pieces: $'+cost.sum.toFixed(2)+(cost.complete?'':' + unpriced pieces'):'Earlier palette plan · no shopping total'}</p><p>${esc(l.profile?.context||'Interview')} · ${esc(l.profile?.fit||l.fit)} fit preference</p><p>Check actual comfort and program instructions before choosing.</p></div>`;}).join('')}</section>`:''}<section class="optin-feedback"><h3>Ask for feedback, on your terms.</h3><p>Create a text brief about your outfit to share yourself. Photos and personal profile fields are excluded. Community publishing remains unavailable.</p><label><input type="checkbox" id="feedbackOptin"> Include only my saved outfit names and selected product names in a downloadable brief.</label><button class="btn plain sm" id="downloadFeedback" disabled>Download my feedback brief</button></section>`;h.querySelectorAll('[data-wear]').forEach(b=>b.onclick=()=>{store.set('selectedLook',+b.dataset.wear);renderWardrobe();announce('Interview look selected.');});h.querySelectorAll('[data-complete-edit]').forEach(b=>b.onclick=()=>{const l=w.find(x=>x.id===+b.dataset.completeEdit);if(l.pieces){outfitDraft={name:l.name,pieces:{...l.pieces},kind:l.kind};styleProfile={...styleProfile,...l.profile};editOutfitId=l.id;store.set('outfitDraft',outfitDraft);store.set('styleProfile',styleProfile);}else{look={...l};seedOutfit(l.presentation||styleProfile.presentation);outfitDraft.name=l.name;editOutfitId=l.id;}location.hash='#dress';});h.querySelectorAll('[data-compare-look]').forEach(b=>b.onclick=()=>{const id=+b.dataset.compareLook;if(compareIds.includes(id))compareIds=compareIds.filter(x=>x!==id);else if(compareIds.length<2)compareIds.push(id);else{announce('Choose at most two looks. Remove one comparison first.');return;}renderWardrobe();announce(compareIds.length+' looks selected for comparison.');});h.querySelectorAll('[data-complete-delete]').forEach(b=>b.onclick=()=>{const id=+b.dataset.completeDelete;store.set('wardrobe',w.filter(x=>x.id!==id));if(sel===id)store.set('selectedLook',null);renderWardrobe();announce('Saved look removed from this device.');});const opt=document.getElementById('feedbackOptin');if(opt){opt.onchange=()=>document.getElementById('downloadFeedback').disabled=!opt.checked;document.getElementById('downloadFeedback').onclick=()=>{if(!opt.checked)return;const text='MissionMed outfit feedback brief\n\nPlease comment on coherence, interview context and practical fit checks, never the person.\n\n'+w.map(l=>l.name+'\n'+outfitProducts(l).map(p=>'• '+p.name).join('\n')).join('\n\n');const blob=new Blob([text],{type:'text/plain'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='my-interview-outfit-feedback.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);announce('Private text brief downloaded. No photo or profile shared.');};}bindEditorial(h);};
const kitRenderBeforeCompletion=renderKit;renderKit=function(){kitRenderBeforeCompletion();document.querySelectorAll('#kit .kit-item').forEach((e,n)=>{const saved=kit.list()[n],i=allItems().find(x=>x.key===saved?.key);if(i?.image)e.insertAdjacentHTML('afterbegin',`<img class="kit-photo" src="${assetFor(i.image)}" alt="${esc(i.name)}" loading="lazy">`);});};
const commIntro=comm.querySelector('.route-intro');[...comm.children].filter(x=>x!==commIntro).forEach(x=>x.remove());comm.insertAdjacentHTML('beforeend',`<div class="editorial-note">Editorial examples, not student submissions. No user photos, votes or publication are collected. Save a look privately; feedback exports require your explicit opt-in.</div><h2 class="sr-only">Editorial outfit gallery</h2><div class="community-editorials">${FASHION.outfits.slice(0,3).map(o=>`<article class="reveal">${boardHTML(o)}<button class="btn ghost" data-editorial-outfit="${o.id}">Make this my starting point →</button></article>`).join('')}</div>`);comm.querySelectorAll('[data-editorial-outfit]').forEach(b=>b.onclick=()=>{const o=FASHION.outfits.find(x=>x.id===b.dataset.editorialOutfit);outfitDraft={name:o.name,pieces:{...o.pieces},kind:o.kind};styleProfile.presentation=o.presentation;store.set('styleProfile',styleProfile);store.set('outfitDraft',outfitDraft);editOutfitId=null;location.hash='#dress';});

/* Visible motion on the existing app, with a complete static alternative. */
const syncMotionBeforeCompletion=syncMotion;syncMotion=function(){syncMotionBeforeCompletion();if(paused||motionQuery.matches){document.querySelectorAll('[data-parallax]').forEach(e=>e.style.setProperty('--story-y','0px'));document.querySelector('.page.active')?.getAnimations().forEach(a=>a.cancel());}};
document.getElementById('motionToggle').onclick=()=>{paused=!paused;store.set('motionPaused',paused);syncMotion();};
let storyFrame=0;function moveStory(){storyFrame=0;if(paused||motionQuery.matches)return;document.querySelectorAll('.page.active [data-parallax]').forEach(el=>{const r=el.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)return;const limit=innerWidth<820?35:78;el.style.setProperty('--story-y',Math.max(-limit,Math.min(limit,(innerHeight*.45-r.top-r.height*.25)*.18))+'px');});}
window.addEventListener('scroll',()=>{if(!storyFrame&&!paused&&!motionQuery.matches)storyFrame=requestAnimationFrame(moveStory);},{passive:true});
const routeBeforeCompletion=route;route=function(){routeBeforeCompletion();const page=document.querySelector('.page.active'),id=page.id.replace('page-','');if(id==='experts')renderExperts();page.querySelectorAll('.reveal').forEach((el,n)=>el.style.setProperty('--entrance',Math.min(n%4,3)));if(!paused&&!motionQuery.matches&&page.animate)page.animate([{opacity:1,transform:'perspective(1400px) translateY(44px) rotateY(-5deg) scale(.97)'},{opacity:1,transform:'perspective(1400px) translateY(0) rotateY(0) scale(1)'}],{duration:850,easing:'cubic-bezier(.16,1,.3,1)'});moveStory();};
window.addEventListener('pagehide',()=>{if(studioFaceURL)URL.revokeObjectURL(studioFaceURL);if(bodyPhotoURL)URL.revokeObjectURL(bodyPhotoURL);studioFaceURL=bodyPhotoURL='';});
syncMotion();route();
